-- NOT APPLIED. Parked in prisma/migrations-pending/ for the OWNER to run (Supabase SQL editor, using
-- `apply-in-sql-editor.sql` beside this file, or `pnpm db:deploy` after moving this folder to
-- prisma/migrations/). No agent applies DDL to the live database.
--
-- R2-117/118/119/120. Additive and idempotent: one nullable, unique column.
--
--   1. mis_bom.bom_number TEXT UNIQUE NULL — a human-readable id (BOM-YYYYMM-nnnnn), generated by
--      createBom() going forward. NULL on any BOM created before this migration: it is never
--      backfilled with a fabricated number, the screens show "—" for those, and PO/GRN linking by
--      BOM number simply does not resolve an old, number-less BOM (link by order number still does).
--
-- ORDER OF OPERATIONS: apply BEFORE deploying code built on the current schema.prisma — Prisma
-- selects every scalar column by default, so a deploy before this column exists 500s the BOM,
-- PO and GRN screens.
--
-- ROLLBACK (only if you must undo; code that selects this column must be reverted first):
--   ALTER TABLE mis_bom DROP COLUMN IF EXISTS bom_number;
--   DELETE FROM _prisma_migrations WHERE migration_name = '20261024000001_r2_bom_number';

ALTER TABLE mis_bom ADD COLUMN IF NOT EXISTS bom_number TEXT;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'mis_bom_bom_number_key') THEN
    ALTER TABLE mis_bom ADD CONSTRAINT mis_bom_bom_number_key UNIQUE (bom_number);
  END IF;
END $$;
